def findMin(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    return nums[lo]

reference_solutions.javascript:
function findMin(nums) {
  let lo = 0, hi = nums.length - 1;
  if (nums[lo] <= nums[hi]) return nums[lo]; // not rotated
  // Invariant: nums[lo] is in the left (larger) run, nums[hi] in the right run.
  while (lo + 1 < hi) {
    const mid = (lo + hi) >> 1;
    if (nums[mid] >= nums[0]) lo = mid; else hi = mid;
  }
  return nums[hi];
}

